273:/**
274: * Query-gated bridge for real-browser journey evidence. Snapshot reads are
275: * passive. Its two whitelisted direct-entry preparations are separately gated,
276: * explicitly receipted, and noncertifying; ordinary play mounts no visible
277: * harness and cannot invoke them.
278: */
279:const JourneyRuntimeProbeBridge: React.FC = () => {
280:  useEffect(() => {
281:    if (!probeEnabled()) return undefined;
282:    let diagnosticGazeOwned = false;
283:    const onKeyDown = (event: KeyboardEvent) => {
284:      const target = event.target;
285:      const targetEditable = target instanceof HTMLInputElement
286:        || target instanceof HTMLTextAreaElement
287:        || target instanceof HTMLElement && target.isContentEditable;
288:      recordJourneyGameplayHotkeyBoundary(event.code, targetEditable);
289:    };
290:    const releaseScenario = (scenarioId?: string) => {
291:      if (!diagnosticGazeOwned
292:        || scenarioId && scenarioId !== 'interaction:persistent-scar-arbitration') return;
293:      setCinematicLookWeight(0);
294:      setCinematicLookTarget(null);
295:      setCinematicGazeIntent(null);
296:      diagnosticGazeOwned = false;
297:    };
298:    const prepareScenario = (scenarioId: string): JourneyProbePreparationRecord => {
299:      const story = getStoryStateSnapshot();
300:      const reason = preparationIdentityReason(scenarioId, story.beat);
301:      if (reason) return deniedPreparation(scenarioId, story.beat, reason);
302:
303:      if (scenarioId === 'input:voyage-worker-name') {
304:        return requestJourneyProbePreparation(scenarioId, story.beat);
305:      }
306:
307:      const target = hifiWreckHandle.diagnosisTarget;
308:      if (!target || !hifiWreckHandle.converted) {
309:        return recordJourneyProbePreparation(scenarioId, story.beat, {
310:          status: 'waiting',
311:          handlerId: 'wreck-diagnostic-gaze',
312:          reason: 'wreck-diagnosis-target-not-ready'
313:        });
314:      }
315:      const player = getPlayerWorldPosition();
316:      setCinematicGazeIntent(null);
317:      setCinematicLookTarget(target);
318:      setCinematicLookWeight(1);
319:      diagnosticGazeOwned = true;
320:      return recordJourneyProbePreparation(scenarioId, story.beat, {
321:        status: 'prepared',
322:        handlerId: 'wreck-diagnostic-gaze',
323:        evidence: {
324:          assistance: 'gaze-only',
325:          movedPlayer: false,
326:          playerPosition: player.toArray(),
327:          targetPosition: target.toArray(),
328:          distance: Math.round(player.distanceTo(target) * 1000) / 1000
329:        }
330:      });
331:    };
332:    const bridge: JourneyProbeBridge = {
333:      snapshot: buildSnapshot,
334:      getSnapshot: buildSnapshot,
335:      clearInteractionTrace: clearStoryInteractionTrace,
336:      prepareScenario,
337:      releaseScenario
338:    };
339:    window.__paravoxiaJourneyProbe = bridge;
340:    window.addEventListener('keydown', onKeyDown);
341:    return () => {
342:      releaseScenario();
343:      window.removeEventListener('keydown', onKeyDown);
344:      if (window.__paravoxiaJourneyProbe === bridge) {
345:        delete window.__paravoxiaJourneyProbe;

